export const WAKE_EXPANSION_COUNT=WAKE_EXPANSION_FEATURES.length;
export function wakeExpansionSnapshot(state={}){const p=state.wakeExpansionProgress||{};const v=Object.values(p);return {range:"4501–5000",total:WAKE_EXPANSION_COUNT,verified:v.filter(x=>x?.status==="verified").length,building:v.filter(x=>x?.status==="building").length,planned:v.filter(x=>x?.status!=="verified"&&x?.status!=="building").length,preserveExisting:true};}
export function setWakeExpansionState(state,id,status="building",evidence=""){state.wakeExpansionProgress=state.wakeExpansionProgress||{};state.wakeExpansionProgress[id]={status,evidence,updatedAt:Date.now(),preserveExisting:true};return state;}
export function detectTwoClap(samples=[],options={}){const threshold=Number(options.threshold||0.55),windowMs=Number(options.windowMs||650),now=Date.now();const peaks=[];for(let i=1;i<samples.length-1;i++){if(samples[i]>=threshold&&samples[i]>=samples[i-1]&&samples[i]>=samples[i+1])peaks.push({i,t:now+i,level:samples[i]});}let pair=null;for(let i=1;i<peaks.length;i++){if(peaks[i].t-peaks[i-1].t<=windowMs){pair=[peaks[i-1],peaks[i]];break;}}return {detected:!!pair,confidence:pair?Math.min(1,(pair[0].level+pair[1].level)/2):0,source:"two-clap",pair,threshold,windowMs};}
export function wakeAudioPolicy({speaking=false,quiet=false,breath=false,permission=true}={}){return {listen:permission&&!speaking,ignoreBreath:breath,quietIsNotFailure:quiet||breath,protectFromSelfTrigger:speaking,gracefulDegradation:true};}
export function wakeActivationDecision({wakeWord=false,twoClap=false,confidence=0,enabled=true}={}){return {activated:enabled&&(wakeWord||twoClap)&&confidence>=0.45,source:wakeWord?"wake-word":twoClap?"two-clap":"none",confidence};}
export function wakeExpansionPolicy(){return {wakeWord:true,twoClap:true,longListening:true,breathSafe:true,quietSafe:true,selfTriggerProtection:true,gracefulDegradation:true,backgroundWakeRequiresNative:true,preserveExisting:true};}
